import random
import time
import itertools
import math

def construct():
    points = list(range(16))
    all_triples = list(itertools.combinations(points, 3))
    num_triples = len(all_triples)
    
    # Map triple to index
    triple_to_idx = {t: i for i, t in enumerate(all_triples)}
    
    # Precompute hyperedges (K(2,2,2) configurations)
    # A hyperedge is a set of 8 triples.
    # Generated by choosing 6 distinct points and partitioning into 3 pairs.
    hyperedges = []
    triple_to_hyperedges = [[] for _ in range(num_triples)]
    
    # Iterate over all combinations of 6 points
    for p6 in itertools.combinations(points, 6):
        # p6 is (p0, p1, p2, p3, p4, p5)
        # We need to partition into 3 pairs.
        # There are 15 such partitions.
        
        partitions = [
            [(0,1),(2,3),(4,5)],
            [(0,1),(2,4),(3,5)],
            [(0,1),(2,5),(3,4)],
            [(0,2),(1,3),(4,5)],
            [(0,2),(1,4),(3,5)],
            [(0,2),(1,5),(3,4)],
            [(0,3),(1,2),(4,5)],
            [(0,3),(1,4),(2,5)],
            [(0,3),(1,5),(2,4)],
            [(0,4),(1,2),(3,5)],
            [(0,4),(1,3),(2,5)],
            [(0,4),(1,5),(2,3)],
            [(0,5),(1,2),(3,4)],
            [(0,5),(1,3),(2,4)],
            [(0,5),(1,4),(2,3)]
        ]
        
        for part in partitions:
            # part is list of 3 pairs of relative indices
            # Map relative indices to actual points in p6
            pairs = []
            for r1, r2 in part:
                pairs.append((p6[r1], p6[r2]))
            
            # Generate 8 triples
            h_triples = []
            for i in range(2):
                for j in range(2):
                    for k in range(2):
                        a = pairs[0][0] if i == 0 else pairs[0][1]
                        b = pairs[1][0] if j == 0 else pairs[1][1]
                        c = pairs[2][0] if k == 0 else pairs[2][1]
                        t = tuple(sorted((a, b, c)))
                        h_triples.append(t)
            
            # Convert to indices
            h_indices = [triple_to_idx[t] for t in h_triples]
            hyperedges.append(h_indices)
            
            # Update triple_to_hyperedges
            h_idx = len(hyperedges) - 1
            for t_idx in h_indices:
                triple_to_hyperedges[t_idx].append(h_idx)
                
    num_hyperedges = len(hyperedges)
    
    best_set = set()
    best_size = 0
    start_time = time.time()
    time_limit = 115
    
    random.seed(42)
    
    # Simulated Annealing
    def run_sa(seed):
        random.seed(seed)
        
        # Initial state: Greedy construction
        current_set = set()
        counts = [0] * num_hyperedges
        
        # Greedy initialization
        indices = list(range(num_triples))
        random.shuffle(indices)
        for t_idx in indices:
            # Check validity
            valid = True
            for h_idx in triple_to_hyperedges[t_idx]:
                if counts[h_idx] == 7:
                    valid = False
                    break
            if valid:
                current_set.add(t_idx)
                for h_idx in triple_to_hyperedges[t_idx]:
                    counts[h_idx] += 1
                    
        # Try to add remaining valid triples
        for t_idx in range(num_triples):
            if t_idx not in current_set:
                valid = True
                for h_idx in triple_to_hyperedges[t_idx]:
                    if counts[h_idx] == 7:
                        valid = False
                        break
                if valid:
                    current_set.add(t_idx)
                    for h_idx in triple_to_hyperedges[t_idx]:
                        counts[h_idx] += 1

        current_score = len(current_set)
        best_local_set = set(current_set)
        best_local_score = current_score
        
        # Annealing parameters
        T = 50.0  # Initial temperature
        cooling_rate = 0.995
        min_T = 0.1
        
        # List of triples not in set for faster sampling? 
        # We can just pick random triple from 0..N-1
        
        while T > min_T and time.time() - start_time < time_limit:
            # Pick a random move: add, remove, or swap
            move_type = random.random()
            
            if move_type < 0.33:
                # Add a random triple
                t_idx = random.randint(0, num_triples - 1)
                if t_idx in current_set:
                    continue
                
                # Check if adding is valid
                valid = True
                for h_idx in triple_to_hyperedges[t_idx]:
                    if counts[h_idx] == 7:
                        valid = False
                        break
                
                if valid:
                    # Accept if valid (score increases)
                    current_set.add(t_idx)
                    for h_idx in triple_to_hyperedges[t_idx]:
                        counts[h_idx] += 1
                    current_score += 1
                    if current_score > best_local_score:
                        best_local_score = current_score
                        best_local_set = set(current_set)
                else:
                    # Invalid move, reject
                    pass
                    
            elif move_type < 0.66:
                # Remove a random triple
                if not current_set:
                    continue
                t_idx = random.choice(list(current_set))
                
                # Always accept removal (score decreases, but might allow future additions)
                current_set.discard(t_idx)
                for h_idx in triple_to_hyperedges[t_idx]:
                    counts[h_idx] -= 1
                current_score -= 1
                
            else:
                # Swap: remove one, add one
                if not current_set:
                    continue
                t_out = random.choice(list(current_set))
                t_in = random.randint(0, num_triples - 1)
                
                if t_in in current_set and t_in != t_out:
                    continue
                
                # Check if t_in is valid if t_out is removed
                # Temporarily remove t_out
                current_set.discard(t_out)
                for h_idx in triple_to_hyperedges[t_out]:
                    counts[h_idx] -= 1
                    
                valid = True
                for h_idx in triple_to_hyperedges[t_in]:
                    if counts[h_idx] == 7:
                        valid = False
                        break
                
                if valid:
                    # Accept swap (score stays same, or we might add more later)
                    current_set.add(t_in)
                    for h_idx in triple_to_hyperedges[t_in]:
                        counts[h_idx] += 1
                    # Score unchanged
                else:
                    # Revert
                    current_set.add(t_out)
                    for h_idx in triple_to_hyperedges[t_out]:
                        counts[h_idx] += 1

            # Cooling
            T *= cooling_rate
            
        # Final greedy pass
        for t_idx in range(num_triples):
            if t_idx not in current_set:
                valid = True
                for h_idx in triple_to_hyperedges[t_idx]:
                    if counts[h_idx] == 7:
                        valid = False
                        break
                if valid:
                    current_set.add(t_idx)
                    for h_idx in triple_to_hyperedges[t_idx]:
                        counts[h_idx] += 1
        current_score = len(current_set)
        if current_score > best_local_score:
            best_local_score = current_score
            best_local_set = set(current_set)

        return best_local_set, best_local_score

    attempts = 0
    while time.time() - start_time < time_limit:
        attempts += 1
        current_set, current_size = run_sa(attempts)
        
        if current_size > best_size:
            best_size = current_size
            best_set = set(current_set)
            
        # If we've reached a very high number, we can stop or continue
        # The maximum possible is C(16,3) = 560. 
        # Excluding K(2,2,2) will be significantly less.
        # Let's run as many attempts as possible.
        
    # Convert best_set indices back to triples
    return [list(all_triples[i]) for i in best_set]
